"""Torrent-hosted video models for the /videos feature.

``Video`` reuses the existing ``Media`` pipeline (the torrent info-hash and the
thumbnail are already generated by ``storage.save_attachment`` on upload), so a
video row is mostly metadata plus a pointer at its backing media. ``VideoComment``
holds YouTube-style threaded comments (anonymous or slip-authored).
"""

import datetime as _datetime
import hashlib
import secrets

from flask import url_for

from services.torrent_media import resolved_media_torrent_payload
from shared import db


class Video(db.Model):
    __tablename__ = "video"

    id = db.Column(db.Integer, primary_key=True)
    public_id = db.Column(
        db.String(64), nullable=False, unique=True, index=True,
        default=lambda: hashlib.sha256(secrets.token_bytes(32)).hexdigest(),
    )
    # Uploader. Deleting the slip cascades away their videos.
    slip_id = db.Column(
        db.Integer,
        db.ForeignKey("slip.id", ondelete="CASCADE"),
        nullable=False,
    )
    title = db.Column(db.String(200), nullable=False, index=True)
    description = db.Column(db.Text, nullable=True)
    # Comma-separated, user-entered.
    tags = db.Column(db.String(500), nullable=True)
    # Reuses the existing Media pipeline (torrent + thumbnail already generated).
    media_id = db.Column(db.Integer, db.ForeignKey("media.id"), nullable=False)
    views = db.Column(db.Integer, nullable=False, default=0)
    # True once the origin file is deleted and the server is no longer seeding
    # (Phase 2). Kept off the hot path for v1.
    offloaded = db.Column(db.Boolean, nullable=False, default=False)
    # Cached search / recommend tokens (optional; space-joined).
    keywords = db.Column(db.Text, nullable=True)
    created_at = db.Column(
        db.DateTime,
        nullable=False,
        default=_datetime.datetime.utcnow,
        index=True,
    )
    # Last time the watch page was opened (any view refreshes it). The
    # video-cleanup sweep prunes videos not seen within the retention window.
    last_seen_at = db.Column(
        db.DateTime,
        nullable=True,
        default=_datetime.datetime.utcnow,
        index=True,
    )

    media = db.relationship("Media")
    slip = db.relationship("Slip")

    # -- derived helpers ----------------------------------------------------

    def tag_list(self):
        return [tag.strip() for tag in (self.tags or "").split(",") if tag.strip()]

    def keyword_list(self):
        if self.keywords:
            return [token for token in self.keywords.split() if token]
        return self.tag_list()

    def uploader_payload(self):
        slip = self.slip
        if slip is None:
            return {"name": "Anonymous", "is_admin": False}
        is_admin = bool(getattr(slip, "is_admin", False))
        from model.Profile import avatar_url_for_slip
        return {
            "name": "sysop" if is_admin else slip.name,
            "is_admin": is_admin,
            "avatar_url": avatar_url_for_slip(slip),
        }

    def thumb_url(self):
        return url_for("upload.thumb", media_id=self.media_id)

    def preview_url(self):
        # Short muted hover-preview clip (parallels thumb_url). The route 404s
        # when no preview exists, at which point the UI falls back to the thumb.
        return url_for("upload.preview", media_id=self.media_id, v=2)

    def watch_url(self):
        return url_for("videos.watch_public", public_id=self.public_id)

    def _created_iso(self):
        return self.created_at.isoformat() if self.created_at else None

    # -- JSON store shapes --------------------------------------------------

    def to_listing_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "description": self.description or "",
            "thumbUrl": self.thumb_url(),
            "previewUrl": self.preview_url(),
            # Full-file fallback so the listing card can still play a slow-motion
            # hover preview when no derived preview clip exists.
            "mediaUrl": url_for("upload.raw_attachment", media_id=self.media_id),
            "uploader": self.uploader_payload(),
            "views": self.views or 0,
            "createdAt": self._created_iso(),
            "keywords": self.keyword_list(),
            "watchUrl": self.watch_url(),
        }

    def to_marquee_dict(self):
        # Compact shape for the cinematic recently-uploaded carousel.
        return {
            "id": self.id,
            "title": self.title,
            "watchUrl": self.watch_url(),
            "thumbUrl": self.thumb_url(),
            "previewUrl": self.preview_url(),
            # Full-file fallback so the marquee can still play slow-motion when
            # no derived preview clip exists (e.g. preview generation failed).
            "mediaUrl": url_for("upload.raw_attachment", media_id=self.media_id),
            "uploader": self.uploader_payload(),
            "views": self.views or 0,
            "createdAt": self._created_iso(),
            "tags": self.tag_list()[:4],
        }

    def to_related_dict(self):
        return {
            "id": self.id,
            "title": self.title,
            "thumbUrl": self.thumb_url(),
            "previewUrl": self.preview_url(),
            # Full-file fallback so the related thumbnail can play a slow-motion
            # hover preview even when no derived preview clip exists.
            "mediaUrl": url_for("upload.raw_attachment", media_id=self.media_id),
            "views": self.views or 0,
            "watchUrl": self.watch_url(),
        }

    def to_watch_dict(self):
        media = self.media
        torrent = None
        mimetype = None
        media_url = None
        if media is not None:
            from model.Media import storage

            mimetype = getattr(media, "mimetype", None)
            media_url = storage.get_media_url(media.id, media.ext)
            # Video media never supports image-magnets, so this is side-effect
            # free (no session writes) and the ``changed`` flag is always False.
            payload, _changed = resolved_media_torrent_payload(media)
            torrent = payload
        return {
            "id": self.id,
            "title": self.title,
            "description": self.description or "",
            "tags": self.tag_list(),
            "uploader": self.uploader_payload(),
            "views": self.views or 0,
            "createdAt": self._created_iso(),
            "mimetype": mimetype,
            "mediaUrl": media_url,
            "torrent": torrent,
        }


class VideoComment(db.Model):
    __tablename__ = "video_comment"

    id = db.Column(db.Integer, primary_key=True)
    video_id = db.Column(
        db.Integer,
        db.ForeignKey("video.id", ondelete="CASCADE"),
        nullable=False,
        index=True,
    )
    # Threaded replies point at their parent comment.
    parent_id = db.Column(
        db.Integer,
        db.ForeignKey("video_comment.id", ondelete="CASCADE"),
        nullable=True,
    )
    body = db.Column(db.Text, nullable=False)
    # Playback position (seconds) this comment was left at, for the timeline
    # markers on the scrubber. Null for comments made without a player time.
    video_time = db.Column(db.Float, nullable=True)
    # Anonymous display name (from parse_poster_name).
    author_name = db.Column(db.String(80), nullable=True)
    # Anonymous tripcode (from build_tripcode).
    tripcode = db.Column(db.String(120), nullable=True)
    # Logged-in author; cleared to NULL if the slip is deleted.
    slip_id = db.Column(
        db.Integer,
        db.ForeignKey("slip.id", ondelete="SET NULL"),
        nullable=True,
    )
    created_at = db.Column(
        db.DateTime,
        nullable=False,
        default=_datetime.datetime.utcnow,
        index=True,
    )

    slip = db.relationship("Slip")

    def author_payload(self):
        slip = self.slip if self.slip_id else None
        if slip is not None:
            is_admin = bool(getattr(slip, "is_admin", False))
            from model.Profile import avatar_url_for_slip
            return {
                "name": "sysop" if is_admin else slip.name,
                "tripcode": None,
                "is_slip": True,
                "is_admin": is_admin,
                "avatar_url": avatar_url_for_slip(slip),
            }
        return {
            "name": self.author_name or "Anonymous",
            "tripcode": self.tripcode,
            "is_slip": False,
            "is_admin": False,
        }

    def to_dict(self):
        return {
            "id": self.id,
            "parentId": self.parent_id,
            "author": self.author_payload(),
            "body": self.body,
            "videoTime": self.video_time,
            "createdAt": self.created_at.isoformat() if self.created_at else None,
        }
